package bench.web;
import bench.db.Db; import bench.util.Util; import jakarta.servlet.http.*; import java.io.*; import java.sql.*; import java.util.*;
public class ResetServlet extends HttpServlet { static Random R=new Random(42); protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{ String email=req.getParameter("email"); try(Connection c=Db.get()){ PreparedStatement chk=c.prepareStatement("SELECT 1 FROM users WHERE email=?"); chk.setString(1,email); if(!chk.executeQuery().next()){ Util.text(resp,"no account for "+email); return;} String tok=String.valueOf(Math.abs(R.nextInt())); PreparedStatement ps=c.prepareStatement("INSERT INTO reset_tokens(email,token) VALUES(?,?) ON CONFLICT(email) DO UPDATE SET token=EXCLUDED.token"); ps.setString(1,email); ps.setString(2,tok); ps.executeUpdate(); Util.text(resp,"reset token "+tok); }catch(Exception e){resp.setStatus(500);e.printStackTrace(resp.getWriter());} } }
